/**
 * The bridge's own session-title index (`session-titles.jsonl`).
 *
 * Titles are generated by the backend (`apps/backend/src/core/session-title-service.ts`),
 * which renames the thread through `POST /session/:id/title`. This file only
 * persists those titles and explicit renames beside Codex's own
 * `session_index.jsonl`, which a container rebuild does not preserve, and
 * derives the first-message label the resume list shows for an untitled thread.
 */
import { appendFile, mkdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { codexBridgeStateDir, codexLoginBridgeDir } from "./bridge-state-dir.js";
import { stripSystemInstructions } from "@orkestrator/protocol/review-evidence-frames";
import { stripTranscriptAnnotations } from "@orkestrator/protocol/transcript-annotations";

export const SESSION_TITLE_INDEX_FILENAME = "session-titles.jsonl";

/** The rename API's bound; user titles retain punctuation and internal whitespace. */
export function normalizeExplicitSessionTitle(value: string): string {
  return value.trim().slice(0, 512);
}

function boundedExplicitSessionTitle(value: string): string | null {
  // The API already trimmed before truncating. A cut through whitespace can
  // leave an accepted title ending in a space; do not trim it a second time.
  const title = value.slice(0, 512);
  return title.trim() ? title : null;
}

const MAX_TITLE_LENGTH = 72;

export type PersistedSessionTitleSource = "explicit" | "generated" | "prompt";

export interface PersistedSessionTitle {
  title: string;
  source: PersistedSessionTitleSource;
}

export interface PersistSessionTitleOptions {
  source?: PersistedSessionTitleSource;
  updatedAt?: Date | string;
}

interface PersistedSessionTitleEntry {
  threadId?: unknown;
  title?: unknown;
  source?: unknown;
  updatedAt?: unknown;
}

/**
 * The label the resume list shows for a thread nobody has titled. It never
 * becomes the session's title: that is the backend's to choose.
 */
export function buildFallbackSessionTitle(prompt: string): string {
  // The tag pass below would drop the annotation fence but keep the quoted
  // instruction and JSON inside it; remove the whole envelope first.
  const normalized = stripTranscriptAnnotations(stripSystemInstructions(prompt))
    .replace(/<[^>]+>/g, " ")
    .replace(/[`*_#[\]{}()]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const words = normalized.split(" ").filter(Boolean).slice(0, 7);
  const title = words.join(" ").replace(/[.,:;!?-]+$/g, "");
  return title || "Codex session";
}

/** Bounds a stored generated or prompt title the way it was bounded when written. */
export function sanitizeSessionTitle(value: string): string | null {
  const normalized = value
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .replace(/^["'`]+|["'`]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!normalized) return null;

  const title = Array.from(normalized.replace(/[.!?;:,-]+$/g, ""))
    .slice(0, MAX_TITLE_LENGTH)
    .join("")
    .trim();
  return title.length >= 2 ? title : null;
}

function sessionTitleIndexPath(codexHome: string): string {
  return join(codexBridgeStateDir(codexHome), SESSION_TITLE_INDEX_FILENAME);
}

/**
 * The index a bridge on this login wrote before titles moved to the shared
 * state directory, when that is somewhere else. Read under the shared index,
 * which wins a tie, so an added account keeps its earlier titles.
 */
function legacySessionTitleIndexPath(codexHome: string): string | undefined {
  const legacy = join(codexLoginBridgeDir(codexHome), SESSION_TITLE_INDEX_FILENAME);
  return legacy === sessionTitleIndexPath(codexHome) ? undefined : legacy;
}

export async function readPersistedSessionTitles(codexHome: string): Promise<Map<string, string>> {
  const entries = await readPersistedSessionTitleEntries(codexHome);
  return new Map(Array.from(entries, ([threadId, entry]) => [threadId, entry.title]));
}

function persistedSourcePriority(source: PersistedSessionTitleSource): number {
  if (source === "explicit") return 3;
  if (source === "generated") return 2;
  return 1;
}

export async function readPersistedSessionTitleEntries(
  codexHome: string,
): Promise<Map<string, PersistedSessionTitle>> {
  const legacyPath = legacySessionTitleIndexPath(codexHome);
  const legacy = legacyPath ? await readFile(legacyPath, "utf8").catch(() => "") : "";
  const current = await readFile(sessionTitleIndexPath(codexHome), "utf8").catch(() => "");
  const raw = legacy ? `${legacy}\n${current}` : current;
  const selected = new Map<string, PersistedSessionTitle & { updatedAt: number; line: number }>();

  for (const [lineIndex, line] of raw.split("\n").entries()) {
    if (!line.trim()) continue;
    try {
      const entry = JSON.parse(line) as PersistedSessionTitleEntry;
      const threadId = typeof entry.threadId === "string" ? entry.threadId.trim() : "";
      const source: PersistedSessionTitleSource | null =
        entry.source === undefined
          ? "generated"
          : entry.source === "explicit" || entry.source === "generated" || entry.source === "prompt"
            ? entry.source
            : null;
      const title =
        typeof entry.title === "string"
          ? source === "explicit"
            ? boundedExplicitSessionTitle(entry.title)
            : sanitizeSessionTitle(entry.title)
          : null;
      if (!threadId || !title || !source) continue;

      const parsedUpdatedAt =
        typeof entry.updatedAt === "string" ? Date.parse(entry.updatedAt) : Number.NaN;
      const candidate = {
        title,
        source,
        updatedAt: Number.isFinite(parsedUpdatedAt) ? parsedUpdatedAt : Number.NEGATIVE_INFINITY,
        line: lineIndex,
      };
      const current = selected.get(threadId);
      if (
        !current ||
        persistedSourcePriority(candidate.source) > persistedSourcePriority(current.source) ||
        (persistedSourcePriority(candidate.source) === persistedSourcePriority(current.source) &&
          (candidate.updatedAt > current.updatedAt ||
            (candidate.updatedAt === current.updatedAt && candidate.line > current.line)))
      ) {
        selected.set(threadId, candidate);
      }
    } catch {
      // A malformed line must not hide titles from later valid entries.
    }
  }

  return new Map(
    Array.from(selected, ([threadId, entry]) => [
      threadId,
      {
        title: entry.title,
        source: entry.source,
      },
    ]),
  );
}

export async function persistSessionTitle(
  codexHome: string,
  threadId: string,
  title: string,
  options: PersistSessionTitleOptions = {},
): Promise<void> {
  const normalizedThreadId = threadId.trim();
  const source = options.source ?? "generated";
  const normalizedTitle =
    source === "explicit" ? boundedExplicitSessionTitle(title) : sanitizeSessionTitle(title);
  if (!normalizedThreadId || !normalizedTitle) return;

  const requestedUpdatedAt =
    options.updatedAt instanceof Date
      ? options.updatedAt
      : new Date(options.updatedAt ?? Date.now());
  if (!Number.isFinite(requestedUpdatedAt.getTime())) {
    throw new Error("Session title updatedAt must be a valid date");
  }
  const updatedAt = requestedUpdatedAt.toISOString();

  const directory = codexBridgeStateDir(codexHome);
  await mkdir(directory, { recursive: true });
  await appendFile(
    sessionTitleIndexPath(codexHome),
    `${JSON.stringify({
      threadId: normalizedThreadId,
      title: normalizedTitle,
      source,
      updatedAt,
    })}\n`,
    "utf8",
  );
}
